    "hi": "निम्नलिखित काव्यांश को ध्यानपूर्वक उस आधारित पूछे गए प्रश्नों के उत्तर लिखिए : गाँव में वो दिन था इतवार । मैं नन्हीं पीढ़ी का हाथ थाम निकल गई बाज़ार । सूखे दरख़्तों के बीच देख एक पतली पगडंडी मैंने नन््हीं पीढ़ी से कहा देखो, यही थी कभी गाँव की नदी आगे देख ज़मीन बड़ी सी दरार मैंने कहा, इसी में समा गए सारे पहाड़ । नन्हीं पीढ़ी दौड़ी : हम आ गए बाज़ार ! क्या क्या लेना है? पूछने लगा दुकानदार । भैया ! थोड़ी बारिश, थोड़ी गीली मिट्टी, एक बोतल नदी, वो डिब्बाबंद पहाड़ उधर दीवार टँगी एक प्रकृति भी दे दो, और ये बारिश इतनी महँगी क्यों? दुकानदार बोला : यह नमी यहाँ की नहीं ! दूसरे से आई है, मंदी है, छटाँक भर मँगाई है। पैसे निकालने को साड़ी की कोर टटोली",
