    "hi": "त्राएँ हमें बेहतर मनुष्य बनाती हैं संकेत बिंदु सांस्कृतिक, भौगोलिक जानकारी भिन्न परिवेश और मान्यताएँ अनुभव की व्यापकता ( ) उत्तम स्वास्थ्य : सबसे बड़ा धन संकेत बिंदु स्वस्थ शरीर में ही स्वस्थ मन विचार « स्वस्थ तन मन से ही सभी कार्य संभव « स्वास्थ्य रक्षा के लिए आवश्यक कदम ( ) मैंने बैंक में खाता खुलवाया संकेत बिंदु खाता खुलवाने की प्रक्रिया की जानकारी आवश्यक दस्तावेज़ों सहित बैंक जाना खाता खुलवाना और प्रसन्नता का अनुभव",
