    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक उस आधारित पूछे गए प्रश्नों के उत्तर लिखिए हम छोटे थे, हमें सिखाया गया कि होशियार बनो। अच्छे नंबर लाओ। जीत कर दिखाओ। धीरे धीरे ये तमाम सीखें आदत में गईं और पता भी नहीं चला कि ये आदत हमारे मन की एक दौड़ में गईं। दूसरों से आगे निकलने की दौड़। कभी कक्षा में प्रथण आने की, कभी ऑफिस में पदोन्नति की, कभी समाज में इज़्जत कमाने की और कभी अपने ही भाई बहनों, दोस्तों, रिश्तेदारों से बेहतर दिखने की परंतु इस लगातार चलने वाली दौड़ में हम भूल गए कि जिस आत्मा को लेकर निकले थे, वह कहाँ है? हर सुबह उठते हैं और सोचते हैं कि किसे पछाड़ना है । हर शाम थककर सोते हैं और गिनते हैं कि कितने पीछे रह गए। यह थकान सिर्फ शरीर की नहीं है, आत्मा की थकान भी है क्योंकि हमने अपनी गति किसी और की रफ़्तार से बाँध दी है। हम अपने फैसले किसी और की कामयाबी देखकर लेने लगे हैं। वो किताब क्यों रहे हो? क्योंकि पढ़ रहे हैं। वो कोर्स क्यों कर रहे हो? क्योंकि उससे नौकरी मिलती है। शहर क्यों जा रहे हो? क्योंकि वहाँ ज़्यादा अवसर हैं। और धीरे धीरे हमारी ज़िंदगी, हमारी नहीं रह जाती। वह एक बन जाती है, दूसरों के रास्तों की, दूसरों के सपनों की। ऐसा नहीं है कि प्रतिस्पर्धा बुरी चीज है। आपको अगर किसी से आगे ही निकलना है, तो उस आप' से निकलिए, जो डरता है, जो टालता है, जो रोज़ कहता है (कल से । आपका अपना असली प्रतिद्वंद्वी कोई और नहीं, हमारा ही कल का, हमारा ही पुराना संस्करण है। आज के इस प्रतिस्पर्धात्मक युग में, जहाँ सोशल मीडिया हर दिन दूसरों की उपलब्धियों को चमका कर पेश करता है, वहाँ अपने ही भीतर स्थिर रहना एक साधना है। खुशी और संतोष हमेशा भीतर से आते हैं और उनका रास्ता",
