    "hi": "मुनिपद कमल बंदि दोउ भ्राता काव्य पंक्ति में अलंकार पहचानकर लिखिए । ( ) “उर विहग सा उड़ रहा नील गगन के बीच' काव्य पंक्ति में अलंकार पहचानकर लिखिए । ( ) वह शर इधर गांडीव गुण से भिन्न जैसे ही हुआ। से जयद्रथ का उधर सिर छिन्न वैसे ही हुआ । काव्य पंक्ति में अलंकार पहचानकर उसका नाम लिखिए । ( ). मानवीकरण अलंकार का एक उपयुक्त उदाहरण लिखिए। ( ) उठ्परोक्षा अलंकार का एक उपयुक्त उदाहरण लिखिए। प, , . . (पाठ्य पुस्तक एवं पूरक पाठ्य पुस्तक) निर्धारित पाठों के आधार निम्नलिखित चार प्रश्नों में से किन््हीं तीन प्रश्नों के उत्तर लगभग 60 शब्दों में लिखिए : . हालदार साहब ने नेताजी की मूर्ति असली चश्मा देखा तो उनके मन में कौन कौन से भाव उभरे ? किन्हीं दो का उल्लेख करते हुए लिखिए कि मूर्ति असली चश्मा क्यों लगा था? ( ). क्या आप बालगोबिन भगत की इस मान्यता से सहमत हैं कि सुस्त और बोदे लोग निगरानी और मुहब्बत के ज़्यादा हकदार होते हैं ? उचित तर्कों के साथ उत्तर लिखिए । ( ) बिस्मिल्ला खाँ के व्यक्तित्व के गुणों का उल्लेख करते हुए लिखिए कि आप उनके किस गुण को अपनाना चाहेंगे और क्यों ? वास्तविक अर्थों में एक संस्कृत मनुष्य कौन कहलाएगा ? संस्कृति” पाठ के संदर्भ में लिखिए। निम्नलिखित पठित गद्यांश आधारित बहुविकल्पी प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : हम उन्होंने अपने अकेले के बल बूते और हौसले से अंग्रेज़ी हिंदी शब्दकोश (विषयवार) के अधूरे काम को आगे बढ़ाना शुरू किया जो अपनी तरह का पहला और अकेला शब्दकोश था। इसने उन्हें यश और प्रतिष्ठा तो बहुत दी, अर्थ नहीं और शायद गिरती आर्थिक स्थिति ने ही उनके व्यक्तित्व के सारे सका",
