    "hi": "निम्नलिखित पठित गद्यांश आधारित बहुविकल्पी प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : गाड़ी छूट रही थी सेकंड क्लास के एक छोटे डिब्बे को खाली समझकर, जरा दौड़कर उसमें गए । अनुमान के प्रतिकूल डिब्बा निर्जन नहीं था। एक पर लखनऊ की नवाबी के एक सफ़ेदपोश बहुत सुविधा से पालथी मारे बैठे थे । सामने दो ताजे चिकने खीरे तौलिए रखे थे । डिब्बे में हमारे सहसा कूद जाने से की आँखों में एकांत चिंतन में विध्म का असंतोष दिखाई दिया । सोचा, हो सकता है, यह भी कहानी के लिए सूझ की चिंता में हों या खीरे जैसी अपदार्थ वस्तु का शौक करते देखे जाने के संकोच में हों। नवाब साहब ने संगति के लिए उत्साह नहीं दिखाया । हमने भी उनके सामने की पर बैठकर आत्मसम्मान में आँखें चुरा लीं। ठाली बैठे, कल्पना करते रहने की पुरानी आदत है। नवाब साहब की असुविधा और संकोच के कारण का अनुमान करने लगे । संभव है, नवाब साहब ने बिलकुल अकेले यात्रा कर सकने के अनुमान में किफ़ायत के विचार से सेकंड क्लास का टिकट खरीद लिया हो और अब गवारा न हो कि शहर का कोई सफ़ेदपोश उन्हें मँझले में करता देखे । ।#",
