    "hi": "निम्नलिखित पठित गद्यांश आधारित बहुविकल्पीय प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : उस समय तक हमारे परिवार में लड़की के विवाह के लिए अनिवार्य योग्यता थी उम्र में सोलह और शिक्षा में मैट्रिक में सुशीला ने यह योग्यता प्राप्त की और शादी करके कोलकाता चली गई । दोनों बड़े भाई भी आगे पढ़ाई के लिए बाहर चले गए । इन लोगों की छत्र छाया के हटते ही पहली बार मुझे नए सिरे से अपने वज़ूद का एहसास हुआ । लड़कियों को जिस उम्र में स्कूली शिक्षा के साथ साथ सुघड़ गृहिणी और कुशल पाक शास्त्री बनने के नुस्खे जुटाए जाते थे, पिताजी का आग्रह रहता था कि मैं रसोई से दूर ही रहूँ रसोई को वे भटियारखाना कहते थे और उनके हिसाब से वहाँ रहना अपनी क्षमता और प्रतिभा को भटूटी में झोंकना था । लड़की की वैवाहिक योग्यता से सिद्ध होता है, उस परिवार की",
