    "en": "",
    "hi": "निम्नलिखित अपठित काव्यांश को ध्यानपूर्वक उस आधारित पूछे गए प्रश्नों के उत्तर लिखिए : पंथ चलना तुझे तो मुस्कुराकर चल मुसाफिर ! वह मुसाफिर कया जिसे कुछ शूल ही के थका दें ? हौसला वह क्या जिसे कुछ मुश्किलें पीछे हटा दें ? वह प्रगति भी क्या जिसे कुछ रंगीन कलियाँ तितलियाँ मुस्कुराकर गुनगुनाकर ध्येय पथ, मंजिल भुला दें ? ज़िंदगी की राह केवल वही पंथी है, आँधियों में, बिजलियों में जो रहे अविचल मुसाफिर ! पंथ चलना तुझे तो मुस्कुराकर चल मुसाफिर ।। जानता तू कि कुछ भी हो तुझे बढ़ना पड़ेगा, आँधियों से ही न खुद से भी तुझे लड़ना पड़ेगा, सामने तक पड़ा कर्त्तव्य पथ तक मनुज ओ ! मौत भी आए अगर तो मौत से भिड़ना पड़ेगा, है अधिक अच्छा यही फिर पंथ चल मुस्कुराता, मुस्कुराती जाए जिससे ज़िंदगी असफल मुसाफिर ! पंथ चलना तुझे तो मुस्कुराकर चल मुसाफिर !",
    "ans": "",
