    "hi": "निम्नलिखित अपठित काव्यांश को ध्यानपूर्वक उस आधारित दिए गए प्रश्नों के उत्तर लिखिए : तुम्हें पता है ? धरती माँ की काया यों तो कोरा है, माटी है । ऊँचे जैसा माथा गहरे मन जैसी घाटी है समतल ये मैदान कि जैसे गोद हमारी माता की है दूध धार सी नदियाँ हैं । माणिक मोती जैसे रत्नों की मंजूषा है फैला सागर । क्या तुमने इस काया के बंजर देखे ? भुनती तपती रेत भभकती भट्टी जैसी ? तुमने मुझे जहाँ से काटा, खोदा और उखाड़ा से वंशनाश कर मुझे मिटाया । अब बोलो, कैसे लगता है ? वहाँ कभी रहने बसने को मन करता है उस बंजर में उस मरुस्थल में ? ? रुको, रुको सोचो, भर रुको । मैं अपनी धरती माता का रक्षा कबच वृक्ष हूँ भाई ! मुझे न काटो मैं तुम्हारा वृक्षमित्र हूँ । इस कविता का वर्ण्य विषय क्या है ?",
