    "hi": "निम्नलिखित अपठित गद्यांश को ध्यानपूर्वक उस आधारित दिए गए प्रश्नों के उत्तर लिखिए ; भारत में कहानियों की सुदृढ़ परंपरा रही है । कहानियाँ आनंद प्रदान करने के साथ साथ, बच्चों के चिंतन को विस्तार देती हैं, उनमें कल्पनाशीलता जगाती हैं तथा उनके समझ के क्षितिज को विस्तृत करती हैं । पंचतंत्र तथा जातक कथाएँ हज़ारों साल से हमारे समाज में लोकप्रिय रही हैं । पंडित विष्णु शर्मा रचित पंचतंत्र की गिनती दुनिया की श्रेष्ठटम बाल कथाओं में की जाती है । इन कथाओं में नैतिक मूल्य निहित हैं । आज दुनियाभर के शिक्षाशासत्री तथा बाल मनोविज्ञानी इस बात को स्वीकार करते हैं कि बच्चों के कल्पना जगत में पशु पक्षियों का अप्रतिम स्थान होता है । वे स्वाभाविक रूप से इनकी ओर आकृष्ट रहते हैं जानवरों की दुनिया में उनमें रुचि, कौतूहल तथा जिज्ञासा होती है । पंचतंत्र की कहानियों में पशु पक्षियों में उसी तरह से संवाद होता है जैसे कि मानव समाज में होता है । इन कहानियों के माध्यम से सच्चाई, त्याग, क्षमा, करुणा, स्नेह जैसे मानवीय मूल्यों को संप्रेषित करने की कोशिश की गई है । ये सभी मूल्य मानव समाज के लिए नितांत जरूरी हैं इन कथाओं के माध्यम से वास्तव में बालमन में जीवन मूल्यों का बीजारोपण होता है । पंचतंत्र की कहानियाँ पाँच खंडों में विभकत हैं, जिन्हें तंत्र कहा गया है । पाँच तंत्रों के समावेश के कारण इन्हें पंचतंत्र कहा गया । आज से करीब दो हज़ार साल पहले लिखी गयी पंचतंत्र की कहानियाँ कालजयी हैं । माना जाता है कि यह दुनिया की सर्वाधिक भाषाओं में अनूदित भारतीय साहित्य है । हमारे देश में विद्यालयीन पर हिन्दी, संस्कृत तथा अंग्रेजी की किताबों में ये कहानियाँ हमेशा से पाठ्यक्रम का हिस्सा रही हैं दुनिया",
