    "hi": "(ख) “हमारे जीवन की रफ़्तार गई है । यहाँ कोई चलता नहीं, बल्कि दौड़ता है कोई बोलता नहीं बकता है । हम अकेले पड़ते हैं अपने आप से लगातार बड़बड़ाते रहते हैं? लेखक के मित्र ने इस स्थिति के क्या कारण बताए हैं और इसके क्या दुष्परिणाम वहाँ दिखाई दे रहे हैं ? झेन की देन पाठ के आधार पर लिखिए",
